import 'package:flutter/material.dart';
import '../../core/network/api_client.dart';
import '../maintenance/maintenance_page.dart';

class SettingsPage extends StatefulWidget{const SettingsPage({super.key,required this.client});final ApiClient client;@override State<SettingsPage> createState()=>_SettingsPageState();}
class _SettingsPageState extends State<SettingsPage>{late Future<List<dynamic>> future;bool busy=false;@override void initState(){super.initState();load();}void load()=>setState(()=>future=Future.wait([widget.client.system(),widget.client.devices(),widget.client.logs()]));Future<void> run(Future<Map<String,dynamic>> Function() action)async{setState(()=>busy=true);try{final result=await action();if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('${result['message']??'عملیات موفق بود.'}')));load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('عملیات انجام نشد: $e')));}finally{if(mounted)setState(()=>busy=false);}}
  Future<void> sms()async{final controller=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:const Text('تست واقعی پیامک'),content:TextField(controller:controller,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'شماره موبایل مقصد')),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('انصراف')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('ارسال پیامک'))]));if(ok==true&&controller.text.trim().isNotEmpty)await run(()=>widget.client.testSms(controller.text.trim()));controller.dispose();}
  Future<void> revoke(Map<String,dynamic> device)async{final ok=await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:const Text('لغو دسترسی دستگاه'),content:Text('دسترسی «${device['device_name']}» فوراً قطع شود؟'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('انصراف')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('لغو دسترسی'))]));if(ok==true){setState(()=>busy=true);try{await widget.client.revokeDevice((device['id'] as num).toInt());load();}finally{if(mounted)setState(()=>busy=false);}}}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('تنظیمات و امنیت'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>MaintenancePage(client:widget.client))),icon:const Icon(Icons.health_and_safety_outlined)),IconButton(onPressed:load,icon:const Icon(Icons.refresh_rounded))]),body:FutureBuilder<List<dynamic>>(future:future,builder:(context,snapshot){if(snapshot.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(snapshot.hasError)return Center(child:Text(snapshot.error.toString()));final system=Map<String,dynamic>.from(snapshot.data![0] as Map),store=Map<String,dynamic>.from(system['store'] as Map),services=Map<String,dynamic>.from(system['services'] as Map),devices=snapshot.data![1] as List,logs=snapshot.data![2] as List;final tapin=Map<String,dynamic>.from(services['tapin'] as Map),smsService=Map<String,dynamic>.from(services['sms'] as Map);return ListView(padding:const EdgeInsets.all(16),children:[if(busy)const LinearProgressIndicator(),_Section(title:'فروشگاه',icon:Icons.storefront_outlined,child:Column(children:[_row('نام فروشگاه','${store['name']}'),_row('آدرس','${store['url']}'),_row('واحد پول','${store['currency']}'),_row('منطقه زمانی','${store['timezone']}'),_row('WooCommerce','${store['woocommerce']}'),_row('WordPress','${store['wordpress']}')])) ,_Section(title:'اتصال سرویس‌ها',icon:Icons.hub_outlined,child:Column(children:[_Service(title:'تاپین',configured:tapin['configured']==true,subtitle:services['auto_register']==true?'ثبت خودکار فعال است':'ثبت خودکار غیرفعال است',onTest:busy?null:()=>run(widget.client.testTapin)),const Divider(),_Service(title:'پیامک ${smsService['provider']}',configured:smsService['configured']==true,subtitle:'ارسال آزمایشی واقعی',onTest:busy?null:sms)])),_Section(title:'دستگاه‌های متصل',icon:Icons.devices_other_outlined,child:devices.isEmpty?const Text('دستگاهی متصل نیست.'):Column(children:devices.map((raw){final d=Map<String,dynamic>.from(raw as Map),revoked=d['revoked_at']!=null;return ListTile(contentPadding:EdgeInsets.zero,leading:Icon(revoked?Icons.phonelink_erase_rounded:Icons.phone_android_rounded),title:Text('${d['device_name']}'),subtitle:Text(revoked?'دسترسی لغو شده':'آخرین فعالیت: ${d['last_seen_at']??'-'}'),trailing:revoked?null:TextButton(onPressed:busy?null:()=>revoke(d),child:const Text('لغو دسترسی')));}).toList())),_Section(title:'تاریخچه عملیات',icon:Icons.history_rounded,child:logs.isEmpty?const Text('عملیاتی ثبت نشده است.'):Column(children:logs.map((raw){final l=Map<String,dynamic>.from(raw as Map);return ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.check_circle_outline_rounded),title:Text('${l['message']}'),subtitle:Text('${l['created_at']}'));}).toList()))]);}));
  Widget _row(String title,String value)=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Text(title,style:Theme.of(context).textTheme.bodySmall)),Expanded(flex:2,child:Text(value))]));}
class _Section extends StatelessWidget{const _Section({required this.title,required this.icon,required this.child});final String title;final IconData icon;final Widget child;@override Widget build(BuildContext context)=>Card(margin:const EdgeInsets.only(bottom:12),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[Icon(icon,size:20),const SizedBox(width:8),Text(title,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w800))]),const SizedBox(height:14),child])));}
class _Service extends StatelessWidget{const _Service({required this.title,required this.configured,required this.subtitle,required this.onTest});final String title,subtitle;final bool configured;final VoidCallback? onTest;@override Widget build(BuildContext context)=>ListTile(contentPadding:EdgeInsets.zero,leading:CircleAvatar(backgroundColor:(configured?Colors.green:Colors.orange).withValues(alpha:.12),child:Icon(configured?Icons.check_rounded:Icons.priority_high_rounded,color:configured?Colors.green:Colors.orange)),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(configured?subtitle:'نیازمند پیکربندی در افزونه'),trailing:OutlinedButton(onPressed:configured?onTest:null,child:const Text('تست')));}
